//! Known-answer tests from `vectors/meetup/` (generated by `cargo xtask vectors`).
#![expect(clippy::panic_in_result_fn, reason = "assertions are how tests fail")]

use pingers_geo::{Bearing, Coordinate, Fix, Meters};
use pingers_proto::{E7Coordinate, Lamport, LeafIndex, MeetPoint};
use pingers_testkit::{Vector, load_vectors};
use pingers_time::UnixSeconds;
use serde_json::{Map, Value};

use super::{TestError, TestResult};
use crate::{MeetPointRegister, Observer, TargetPosition, compass, coordinate_to_wire};

fn number(fields: &Map<String, Value>, field: &'static str) -> Result<f64, TestError> {
    fields
        .get(field)
        .and_then(Value::as_f64)
        .ok_or(TestError::Setup(field))
}

fn integer(fields: &Map<String, Value>, field: &'static str) -> Result<i64, TestError> {
    fields
        .get(field)
        .and_then(Value::as_i64)
        .ok_or(TestError::Setup(field))
}

fn unsigned(fields: &Map<String, Value>, field: &'static str) -> Result<u64, TestError> {
    fields
        .get(field)
        .and_then(Value::as_u64)
        .ok_or(TestError::Setup(field))
}

#[test]
fn coordinates_round_to_the_wire_as_the_vectors_say() -> TestResult {
    let file = load_vectors("meetup/coordinate-wire")?;
    for vector in &file.vectors {
        let coordinate = Coordinate::new(
            number(&vector.inputs, "latitude")?,
            number(&vector.inputs, "longitude")?,
        )?;
        let wire = coordinate_to_wire(coordinate)?;
        assert_eq!(
            i64::from(wire.latitude_e7()),
            integer(&vector.expected, "latitude_e7")?,
            "{}",
            vector.name
        );
        assert_eq!(
            i64::from(wire.longitude_e7()),
            integer(&vector.expected, "longitude_e7")?,
            "{}",
            vector.name
        );
    }
    Ok(())
}

fn compass_case(vector: &Vector) -> TestResult {
    let inputs = &vector.inputs;
    let heading = match inputs.get("heading_degrees").and_then(Value::as_f64) {
        Some(degrees) => Some(Bearing::new(degrees)?),
        None => None,
    };
    let observer = Observer {
        fix: Fix {
            coordinate: Coordinate::new(
                number(inputs, "observer_latitude")?,
                number(inputs, "observer_longitude")?,
            )?,
            accuracy: Meters::from_whole(5),
            taken_at: UnixSeconds::new(unsigned(inputs, "now")?),
        },
        heading,
    };
    let target = TargetPosition {
        position: Coordinate::new(
            number(inputs, "target_latitude")?,
            number(inputs, "target_longitude")?,
        )?,
        taken_at: UnixSeconds::new(unsigned(inputs, "taken_at")?),
    };
    let reading = compass(
        &observer,
        &target,
        UnixSeconds::new(unsigned(inputs, "now")?),
    );
    let expected = &vector.expected;
    let name = &vector.name;
    assert!(
        (reading.distance.get() - number(expected, "distance_meters")?).abs() < 0.01,
        "{name}"
    );
    assert!(
        (reading.bearing.degrees() - number(expected, "bearing_degrees")?).abs() < 1e-6,
        "{name}"
    );
    assert_eq!(
        reading.age.as_secs(),
        unsigned(expected, "age_seconds")?,
        "{name}"
    );
    let wanted = expected
        .get("relative_bearing_degrees")
        .and_then(Value::as_f64);
    assert_eq!(
        reading.relative_bearing.is_some(),
        wanted.is_some(),
        "{name}"
    );
    if let (Some(relative), Some(wanted)) = (reading.relative_bearing, wanted) {
        assert!((relative.degrees() - wanted).abs() < 1e-6, "{name}");
    }
    Ok(())
}

#[test]
fn compass_readings_match_the_vectors() -> TestResult {
    let file = load_vectors("meetup/compass")?;
    for vector in &file.vectors {
        compass_case(vector)?;
    }
    Ok(())
}

fn write(fields: &Map<String, Value>) -> Result<(LeafIndex, MeetPoint), TestError> {
    let sender = LeafIndex::new(
        u32::try_from(unsigned(fields, "sender")?).map_err(|_range| TestError::Setup("sender"))?,
    );
    let lamport = Lamport::new(unsigned(fields, "lamport")?);
    let point = match fields.get("kind").and_then(Value::as_str) {
        Some("fixed") => MeetPoint::Fixed {
            position: E7Coordinate::new(0, 0)?,
            label: None,
            lamport,
        },
        Some("at_member") => MeetPoint::AtMember {
            leaf: LeafIndex::new(
                u32::try_from(unsigned(fields, "leaf")?)
                    .map_err(|_range| TestError::Setup("leaf"))?,
            ),
            lamport,
        },
        Some("cleared") => MeetPoint::Cleared { lamport },
        _ => return Err(TestError::Setup("kind")),
    };
    Ok((sender, point))
}

#[test]
fn meet_point_resolution_matches_the_vectors() -> TestResult {
    let file = load_vectors("meetup/meet-point")?;
    for vector in &file.vectors {
        let mut register = MeetPointRegister::new();
        let mut last_sender = None;
        let writes = vector
            .inputs
            .get("writes")
            .and_then(Value::as_array)
            .ok_or(TestError::Setup("writes"))?;
        for entry in writes {
            let fields = entry.as_object().ok_or(TestError::Setup("write"))?;
            let (sender, point) = write(fields)?;
            if register.apply(sender, point) == crate::MeetPointUpdate::Applied {
                last_sender = Some(sender);
            }
        }
        let expected = &vector.expected;
        let name = &vector.name;
        assert_eq!(
            register.lamport(),
            Lamport::new(unsigned(expected, "lamport")?),
            "{name}"
        );
        let kind = match register.current() {
            None => "none",
            Some(MeetPoint::Fixed { .. }) => "fixed",
            Some(MeetPoint::AtMember { .. }) => "at_member",
            Some(MeetPoint::Cleared { .. }) => "cleared",
        };
        assert_eq!(
            Some(kind),
            expected.get("kind").and_then(Value::as_str),
            "{name}"
        );
        if kind != "none" {
            assert_eq!(
                last_sender.map(|leaf| u64::from(leaf.get())),
                Some(unsigned(expected, "sender")?),
                "{name}"
            );
        }
    }
    Ok(())
}
